            };
            _onChange = notify;
            foreach (var b in _binders) b.Subscribe(notify);
            var arrayLoader = new Gs2Bind.Gs2LoginReward.ReceiveStatusArrayLoader("LoginReward");
            _unsubscribers.Add(arrayLoader.Subscribe(
                _gs2,
                _session,
                async (_, _, items) =>
                {
                    if (_disposed) return;
                    try
                    {
                        await ReconcileFromLoginRewardLoginRewardUserItems(items, attachChildSubscribe: true, CancellationToken.None);
                    }
                    catch (Exception ex)
